"""
Library Catalogue System

This module implements classes for managing a library's catalogue, including Books, Members, and Loans.

Features:
- Add and manage books and members
- Create and track loans
- Search books by author or title
- Detect overdue loans
- Calculate fines for overdue loans based on configurable rates
"""

import json
from datetime import datetime, timedelta

class Book:
    """Represents a book in the library."""
    def __init__(self, isbn, title, author, year_published, copies=1):
        self.isbn = isbn
        self.title = title
        self.author = author
        self.year_published = year_published
        self.copies = copies
        self.available_copies = copies

    def __repr__(self):
        return f"<Book ISBN={self.isbn} Title='{self.title}' Author='{self.author}' Available={self.available_copies}/{self.copies}>"

class Member:
    """Represents a library member."""
    def __init__(self, member_id, name, email, max_loans=5):
        self.member_id = member_id
        self.name = name
        self.email = email
        self.max_loans = max_loans
        self.loans = []  # List of Loan instances

    def can_borrow(self):
        return len(self.loans) < self.max_loans

    def __repr__(self):
        return f"<Member ID={self.member_id} Name='{self.name}' Loans={len(self.loans)}>"

class Loan:
    """Represents a loan of a book to a member."""
    def __init__(self, book, member, loan_date=None, due_days=14):
        self.book = book
        self.member = member
        self.loan_date = loan_date or datetime.now()
        self.due_date = self.loan_date + timedelta(days=due_days)
        self.return_date = None

    def is_overdue(self):
        if self.return_date is None and datetime.now() > self.due_date:
            return True
        return False

    def days_overdue(self):
        if self.is_overdue():
            return (datetime.now() - self.due_date).days
        return 0

    def calculate_fine(self, fine_per_day):
        return self.days_overdue() * fine_per_day

    def return_book(self):
        if self.return_date is None:
            self.return_date = datetime.now()
            self.book.available_copies += 1

    def __repr__(self):
        return f"<Loan Book='{self.book.title}' Member='{self.member.name}' Due={self.due_date.date()} Returned={self.return_date}>'"

class Catalogue:
    """Manages library catalogue, members, loans, and configuration."""
    def __init__(self, config_path='config.json'):
        with open(config_path, 'r') as f:
            self.config = json.load(f)
        self.books = {}  # isbn -> Book
        self.members = {}  # member_id -> Member
        self.loans = []  # List of Loan

    def add_book(self, book):
        if book.isbn in self.books:
            existing = self.books[book.isbn]
            existing.copies += book.copies
            existing.available_copies += book.copies
        else:
            self.books[book.isbn] = book

    def add_member(self, member):
        if member.member_id in self.members:
            raise ValueError(f"Member ID {member.member_id} already exists")
        self.members[member.member_id] = member

    def find_books_by_title(self, title):
        title_lower = title.lower()
        return [book for book in self.books.values() if title_lower in book.title.lower()]

    def find_books_by_author(self, author):
        author_lower = author.lower()
        return [book for book in self.books.values() if author_lower in book.author.lower()]

    def loan_book(self, member_id, isbn):
        member = self.members.get(member_id)
        book = self.books.get(isbn)
        if member is None:
            raise ValueError("Member not found")
        if book is None:
            raise ValueError("Book not found")
        if book.available_copies < 1:
            raise ValueError("No available copies")
        if not member.can_borrow():
            raise ValueError("Member has reached loan limit")
        loan_period = self.config.get('loan_period_days', 14)
        loan = Loan(book, member, due_days=loan_period)
        self.loans.append(loan)
        member.loans.append(loan)
        book.available_copies -= 1
        return loan

    def return_book(self, member_id, isbn):
        member = self.members.get(member_id)
        if member is None:
            raise ValueError("Member not found")
        for loan in member.loans:
            if loan.book.isbn == isbn and loan.return_date is None:
                loan.return_book()
                member.loans.remove(loan)
                return loan
        raise ValueError("Loan not found or already returned")

    def get_overdue_loans(self):
        return [loan for loan in self.loans if loan.is_overdue()]

    def calculate_fine(self, loan):
        fine_per_day = self.config.get('fine_rate_per_day', 1.0)
        return loan.calculate_fine(fine_per_day)

    def __repr__(self):
        return f"<Catalogue Books={len(self.books)} Members={len(self.members)} Loans={len(self.loans)}>"

# Additional functionality could be added here (e.g., notifications, reports, etc.)
EOF

